    (hdim : Module.finrank Hᵐᵒᵖ E = n + 1) (u : E) (hu : ‖u‖ = 1) :
    Module.finrank Hᵐᵒᵖ (hermitianNormalHyperplane P u) = n

theorem realHermitianNormalHyperplane_finrank {n : ℕ}
    (hdim : Module.finrank Hᵐᵒᵖ E = n + 1) (u : E) (hu : ‖u‖ = 1) :
    Module.finrank ℝ (realHermitianNormalHyperplane P u) = 4 * n

